/**
 * Assignment bound to the participant code (SPEC/27 §2.2, decision U4; reconciled 5 Oct 2026; stratified 24 Oct 2026).
 *
 * The study's cell comes from a pre-generated allocation table, committed at
 * `content/assignment/allocation.json` and regenerated byte-identically by
 * `tools/assignment/generate.ts` (`npm run assignment:generate`, `--check` to verify). Design:
 *
 * - **Stratified** (SPEC/30 §2 revision (bf), 24 Oct 2026) by session language × profession (fire/rescue, military, other) × leads
 *   others (yes / no): twelve strata, each with its own allocation sequence and its own codes. The profession and the leadership come
 *   from the recruitment screener (the link's `?osite=`, `preview.ts`); the language from the start page or the code. Before:
 *   stratified by language only (`rowsSha256` 4a4b080b…38f2, blocks of 10).
 * - **Permuted blocks of 4**, 2 : 2 for `radio` (Haku) : `reasoning_intent` (the guide), each block a seeded Fisher–Yates shuffle of its
 *   four cells. Small blocks because the strata are many and small (about 100 participants over twelve strata): an unfinished block
 *   leaves a stratum at most two participants out of balance, and the whole table at most a few (Kernan et al. 1999, J Clin Epidemiol
 *   52:19–26). The codes are opaque and issued by the server, so the short block does not let a recruiter predict a cell.
 *   `reasoning_once` is not allocated (SPEC/30 §2).
 * - **One stream per stratum**: each stratum's generator is seeded from the plan's seed and the stratum's id, so a stratum's rows do not
 *   depend on any other stratum's size (blocks can be added to one stratum without changing another's codes or cells).
 * - **opaque codes**: a language letter (`F` fi, `E` en) and five characters drawn by the stratum's stream from an alphabet without
 *   look-alikes; nothing in a code depends on its cell or its stratum (a code already used by an earlier stratum is drawn again);
 * - **deterministic**: splitmix32-seeded xoshiro128**, a fixed seed, no clock, no unseeded randomness; the table carries the hash of
 *   its rows (`rowsSha256`), which the header logs.
 *
 * The participant sees the code (it is in the link), never the cell.
 */

import type { Cell } from "../scenario/types.js";
import { stratumId, type Profession, type Stratum } from "../telemetry/record-kinds-pilot2.js";

export type AssignmentLanguage = "fi" | "en";

/** The cells in block order, before the shuffle: 2 + 2 = 4 (SPEC/30 §2 revision (bf)). */
export const BLOCK_COMPOSITION: readonly { readonly cell: Cell; readonly count: number }[] = [
  { cell: "radio", count: 2 },
  { cell: "reasoning_intent", count: 2 },
];
export const BLOCK_SIZE = 4;

/** One stratum of the plan: the language, the screener's profession and leadership, and its number of blocks. */
export interface AssignmentStratumPlan extends Stratum {
  readonly language: AssignmentLanguage;
  readonly blocks: number;
}

/** The generator's fixed inputs. Changing any of them is a new table (and a new pre-registration entry). */
export interface AssignmentPlan {
  readonly seed: number;
  /** The strata, in table order. */
  readonly strata: readonly AssignmentStratumPlan[];
}

const plan = (language: AssignmentLanguage, profession: Profession, leads: boolean, blocks: number): AssignmentStratumPlan => ({ language, profession, leads, blocks });

/**
 * The committed plan (DRAFT, researcher to confirm the stratum sizes; SPEC/30 §2 revision (bf), 24 Oct 2026): 140 English codes and 68
 * Finnish ones, more than the 100 to be recruited in every stratum's plausible share, so that an unused tail of a stratum, not a change
 * of table, absorbs the unknown split. Leaders are the larger strata (recruitment prioritises them). Codes are issued in table order
 * within a stratum; analysis is by the cell and stratum actually logged. The seed is the study's (unchanged since 5 Oct 2026).
 */
export const ASSIGNMENT_PLAN: AssignmentPlan = {
  seed: 20261005,
  strata: [
    plan("en", "fire_rescue", true, 10), plan("en", "fire_rescue", false, 6),
    plan("en", "military", true, 8), plan("en", "military", false, 5),
    plan("en", "other", true, 3), plan("en", "other", false, 3),
    plan("fi", "fire_rescue", true, 4), plan("fi", "fire_rescue", false, 4),
    plan("fi", "military", true, 3), plan("fi", "military", false, 4),
    plan("fi", "other", true, 1), plan("fi", "other", false, 1),
  ],
};

export interface AssignmentRow {
  readonly code: string;
  readonly language: AssignmentLanguage;
  readonly profession: Profession;
  readonly leads: boolean;
  /** 1-based block number within the stratum (language × profession × leads). */
  readonly block: number;
  readonly cell: Cell;
}

export interface AssignmentTable {
  readonly version: 2;
  readonly generator: string;
  readonly seed: number;
  readonly blockSize: number;
  readonly composition: string;
  readonly strata: AssignmentPlan["strata"];
  /** SHA-256 of `JSON.stringify(rows)`; written by the tool, checked by the test, logged in the header. */
  readonly rowsSha256: string;
  readonly rows: readonly AssignmentRow[];
}

/** A row's stratum besides its language. */
export function stratumOfRow(row: Pick<AssignmentRow, "profession" | "leads">): Stratum {
  return { profession: row.profession, leads: row.leads };
}

/** A row (or plan stratum) is in `s`: the same language, profession and leadership. */
export function inStratum(row: Pick<AssignmentRow, "language" | "profession" | "leads">, language: AssignmentLanguage, s: Stratum): boolean {
  return row.language === language && row.profession === s.profession && row.leads === s.leads;
}

// ---------------------------------------------------------------------------
// Seeded randomness (as tools/power/*.ts)
// ---------------------------------------------------------------------------

function splitmix32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x9e3779b9) >>> 0;
    let z = s;
    z = Math.imul(z ^ (z >>> 16), 0x85ebca6b) >>> 0;
    z = Math.imul(z ^ (z >>> 13), 0xc2b2ae35) >>> 0;
    return (z ^ (z >>> 16)) >>> 0;
  };
}

/** xoshiro128**: a uniform 32-bit integer per call. */
function xoshiro128ss(seed: number): () => number {
  const sm = splitmix32(seed);
  const s = new Uint32Array([sm(), sm(), sm(), sm()]);
  const rotl = (x: number, k: number) => ((x << k) | (x >>> (32 - k))) >>> 0;
  return () => {
    const result = Math.imul(rotl(Math.imul(s[1]!, 5) >>> 0, 7), 9) >>> 0;
    const t = (s[1]! << 9) >>> 0;
    s[2]! ^= s[0]!; s[3]! ^= s[1]!; s[1]! ^= s[2]!; s[0]! ^= s[3]!;
    s[2]! ^= t; s[3] = rotl(s[3]!, 11);
    return result;
  };
}

/** FNV-1a (32-bit) of a string: the stratum's id mixed into the plan's seed. */
function fnv1a(text: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) h = Math.imul(h ^ text.charCodeAt(i), 0x01000193) >>> 0;
  return h >>> 0;
}

/** The seed of one stratum's stream: the plan's seed and the stratum's id (`en.fire_rescue.lead`), never its position or size. */
export function stratumSeed(seed: number, language: AssignmentLanguage, s: Stratum): number {
  return splitmix32((seed ^ fnv1a(`${language}.${stratumId(s)}`)) >>> 0)();
}

/** An unbiased integer in [0, n) by rejection. */
function below(next: () => number, n: number): number {
  const limit = Math.floor(0x100000000 / n) * n;
  for (;;) {
    const x = next();
    if (x < limit) return x % n;
  }
}

/** Code characters: digits and capitals without 0/O, 1/I/L, 5/S, 2/Z, 8/B. */
export const CODE_ALPHABET = "34679ACDEFGHJKMNPQRTUVWXY";
export const CODE_BODY_LENGTH = 5;
const LANGUAGE_LETTER: Readonly<Record<AssignmentLanguage, string>> = { fi: "F", en: "E" };

/** The table's rows from a plan: deterministic in the plan alone; each stratum from its own stream. */
export function generateAssignmentRows(p: AssignmentPlan): AssignmentRow[] {
  const total = BLOCK_COMPOSITION.reduce((n, c) => n + c.count, 0);
  if (total !== BLOCK_SIZE) throw new Error(`block composition sums to ${total}, not ${BLOCK_SIZE}`);
  const rows: AssignmentRow[] = [];
  const used = new Set<string>();
  for (const stratum of p.strata) {
    const next = xoshiro128ss(stratumSeed(p.seed, stratum.language, stratum));
    for (let block = 1; block <= stratum.blocks; block++) {
      const cells: Cell[] = BLOCK_COMPOSITION.flatMap((c) => Array.from({ length: c.count }, () => c.cell));
      for (let i = cells.length - 1; i > 0; i--) { // Fisher–Yates
        const j = below(next, i + 1);
        [cells[i], cells[j]] = [cells[j]!, cells[i]!];
      }
      for (const cell of cells) {
        let code: string;
        do {
          let body = "";
          for (let k = 0; k < CODE_BODY_LENGTH; k++) body += CODE_ALPHABET[below(next, CODE_ALPHABET.length)];
          code = LANGUAGE_LETTER[stratum.language] + body;
        } while (used.has(code));
        used.add(code);
        rows.push({ code, language: stratum.language, profession: stratum.profession, leads: stratum.leads, block, cell });
      }
    }
  }
  return rows;
}

/** A participant code as typed or linked: trimmed, upper case. */
export function normaliseCode(raw: string): string {
  return raw.trim().toUpperCase();
}

/** The table row of a code, or null for a code the table does not hold. */
export function assignmentOf(table: AssignmentTable, rawCode: string): AssignmentRow | null {
  const code = normaliseCode(rawCode);
  return table.rows.find((r) => r.code === code) ?? null;
}
